head.script:
scwin.trigger2_onclick = function(e) {
    var json = dataList1.getAllJSON();
    json.forEach(function(o) {
        o["MENU_NM"] = o["MENU_NM"].replace(/<([^>]+)>/gi, ""); // 태그제거
    });
    dataList1.setJSON(json);
    treeview1.spanAll(true);
    var word = input1.getValue();
    /* 접었다 펴면 스타일 사라짐..
    		treeview1.setCustomFormatter(function(label, formattedLabel, node){
    			var jNode = WebSquare.wUnit.getJq("#treeview1_label_"+node.index).eq(0); 
    		    var html = jNode.html();
    		    html = html.replaceAll(word, "<span style='color:red'>"+word+"</span>");
    		    jNode.html(html);
    		});		

    */
    var arr_idx = dataList1.getMatchedIndex("MENU_NM", word, false);
    arr_idx.forEach(function(ix) {
        var label = dataList1.getCellData(ix, "MENU_NM");
        dataList1.setCellData(ix, "MENU_NM", label.replaceAll(word, "<span style='color:red'>" + word + "</span>"));
    });
    //treeview1.findNodeByValue(word, true);
    //treeview1.spanNode(arr_idx[0], true, true);
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플 실행 후 검색버튼을 클릭한다.
    //1. Click the Search button after running the sample.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. menu1-1 메뉴가 스타일이 적용되어 빨강색으로 보여진다. (이전에는 menu1-1 메뉴가 테그값이 포함되어 보여짐)
    //1. menu1-1 The style is applied to the menu and is shown in red. (Previously menu1-1 menu is shown with tag value)\
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('treeview1_label_2').textContent == 'menu1-1'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('treeview1_label_2').childNodes[0].style.color == 'red'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
